// Basic LLM Chain çıktısını düzgün JSON'a dönüştür
const llmInputItem = $input.first();
let output = {};
let llmError = null;

// Çağrı ID'sini Process Conversation veya Prepare S3 Download'dan al
let callid = 'unknown';
try {
  // create-analysis-prompt node'u $json.callid'yi conversation ile birlikte taşır
  callid = llmInputItem.json.callid || $('Process Conversation').item.json.callid || $('Prepare S3 Download').item.json.callid || 'unknown'; 
} catch (error) {
  console.log('CallID bulunamadı (Format LLM Response):', error.message);
}

if (llmInputItem.json.error) { // LLM Chain'den gelen hata
  llmError = llmInputItem.json.error.message || 'LLM chain bilinmeyen hata';
  console.log('Hata: LLM chain hatası:', llmError);
  output = {
    error: llmError,
    sentiment: "unknown", topic: "unknown", significantterm: "unknown",
    generalvalue: "unknown", generalexperience: "unknown", sale_outcome: "unknown"
  };
} else if (llmInputItem.json && llmInputItem.json.text) {
  let responseText = llmInputItem.json.text;

  // Markdown JSON formatını temizle (Gemini bazen ```json ... ``` ile dönebilir)
  if (responseText.startsWith('```json')) {
    responseText = responseText.substring(7, responseText.length - 3).trim();
  } else if (responseText.startsWith('```')) { // Bazen sadece ``` ile başlayıp bitebiliyor
     responseText = responseText.substring(3, responseText.length - 3).trim();
  }

  try {
    output = JSON.parse(responseText);
    if (output.error === null) { // Prompt'ta error: null istemiştik
        delete output.error; // Eğer analiz başarılıysa error alanını kaldır
    }
  } catch (error) {
    console.log('JSON parse hatası (Format LLM Response):', error.message, 'Raw Text:', responseText);
    llmError = 'LLM yanıtı JSON parse hatası: ' + error.message;
    output = {
      error: llmError,
      raw_text: responseText,
      sentiment: "unknown", topic: "unknown", significantterm: "unknown",
      generalvalue: "unknown", generalexperience: "unknown", sale_outcome: "unknown"
    };
  }
} else {
  llmError = 'LLM chain çıktısı boş veya text alanı yok.';
  console.log('Hata:', llmError);
  output = {
    error: llmError
  };
}

return [{
  json: {
    ...output,
    callid: callid // callid'yi her zaman ekle
  }
}];
